"""Generate the prebuilt static site. No template engine or runtime dependency required."""
from pathlib import Path
from html import escape
import json
import re

ROOT = Path(__file__).resolve().parent.parent / 'holy-elixir'
PAGES = {}
NOTICE = 'We’re updating our website. Some content may reflect earlier information. We are working closely with the relevant authorities to keep our information accurate and improve your experience. Thank you for your patience.'

def image(name, alt, cls='', eager=False, campaign=True, full=False):
    folder='campaign' if campaign else 'lifestyle-v2'
    width = 1254 if name in ('water-terrace','black-occasion') else 1440
    sizes = '100vw' if full else '(max-width: 760px) 100vw, 50vw'
    height = 810 if name=='collection' else 1254 if campaign and name!='ionizer-kitchen' else 960
    return f'<img class="{cls}" src="assets/images/{folder}/{name}-1440.webp" srcset="assets/images/{folder}/{name}-640.webp 640w, assets/images/{folder}/{name}-1440.webp {width}w" sizes="{sizes}" alt="{escape(alt)}" width="{width}" height="{height}" loading="{"eager" if eager else "lazy"}" decoding="async" {"fetchpriority=high" if eager else ""}>'

def link(href, text, secondary=False):
    return f'<a class="button {"button--line" if secondary else ""}" href="{href}">{text}<span aria-hidden="true">↗</span></a>'

def intro(kicker,title,body,extra=''):
    return f'<header class="page-intro wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lede">{body}</p>{extra}</header>'

def split(kicker,title,body,img,alt,reverse=False,campaign=True,extra='',dark=False):
    return f'<section class="section {"midnight" if dark else ""}"><div class="wrap split {"split--reverse" if reverse else ""}"><div class="split-art" data-reveal>{image(img,alt,campaign=campaign)}</div><div class="split-copy" data-reveal><p class="eyebrow">{kicker}</p><h2>{title}</h2>{body}{extra}</div></div></section>'

def cards(items,cls=''):
    return '<div class="cards '+cls+'">'+''.join(f'<article class="text-card" data-reveal><span class="card-number">{i+1:02}</span><h3>{title}</h3><p>{body}</p>{f"<a class=arrow-link href={href}>{cta} <span aria-hidden=true>→</span></a>" if href else ""}</article>' for i,(title,body,href,cta) in enumerate(items))+'</div>'

def section(kicker,title,body='',content='',dark=False):
    return f'<section class="section {"midnight" if dark else ""}"><div class="wrap"><div class="section-head" data-reveal><p class="eyebrow">{kicker}</p><h2>{title}</h2>{f"<p>{body}</p>" if body else ""}</div>{content}</div></section>'

def faq(items):
    return '<div class="faq-list">'+''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><div class="faq-answer">{a}</div></details>' for q,a in items)+'</div>'

def related(items):
    return section('Keep exploring','There’s more to discover.',content=cards(items))

def cta(title='Find your next favourite pause.',body='A product question, a table to set, or a partnership in mind? Let’s start a conversation.',href='contact.html',label='Speak with us'):
    return f'<section class="cta-band"><div class="wrap"><div><p class="eyebrow">Your next step</p><h2>{title}</h2><p>{body}</p></div>{link(href,label)}</div></section>'

def product_cards():
    products=[('01 / Everyday','Alkaline Water','Bright days. A simple refreshment ritual.','alkaline-water.html','water-terrace','Zubrex alkaline water concept on a sunlit terrace'),('02 / Distinctive','Black Drink','A striking presence. A moment to savour.','black-drink.html','black-occasion','Zubrex Black Drink concept on a dark marble occasion table'),('03 / At home','Water Ionizers','Explore a setup that fits your kitchen.','ionizers.html','ionizer-kitchen','Zubrex ionizer concept in a bright kitchen')]
    return '<div class="product-grid">'+''.join(f'<article class="product-card" data-reveal><a class="product-image" href="{href}" aria-label="Discover {name}">{image(img,alt)}</a><div class="product-card-copy"><p class="eyebrow">{num}</p><h3><a href="{href}">{name}</a></h3><p>{body}</p><a class="arrow-link" href="{href}">Discover the details <span aria-hidden="true">↗</span></a></div></article>' for num,name,body,href,img,alt in products)+'</div>'

def product_intro(kicker,title,body,extra,img,alt,number,notes,sections,appliance=False):
    return f'''<header class="product-hero wrap {'product-hero--appliance' if appliance else ''}"><div class="product-hero-copy"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lede">{body}</p><div class="product-notes">{''.join(f'<span>{n}</span>' for n in notes)}</div><div class="actions">{extra}<a class="quiet-link" href="#product-details">Explore the details <span aria-hidden="true">↓</span></a></div><p class="product-edition"><span>{number}</span> The Zubrex collection</p></div><figure class="product-hero-figure"><div class="product-hero-art">{image(img,alt,eager=True)}</div><figcaption><span>Campaign concept</span><a href="terms.html">About our imagery <span aria-hidden="true">↗</span></a></figcaption></figure></header><nav class="product-sections wrap" aria-label="Product sections"><span>Discover more</span>{''.join(f'<a href="#{id_}">{label}<span aria-hidden="true">↘</span></a>' for id_,label in zip(['product-overview','product-details','product-questions'],sections))}</nav>'''

def moment_explorer():
    options=[('daylight','In daylight','01 / The everyday edit','Make a little room<br>for <em>yourself.</em>','A pause between meetings. A quiet corner in the sunshine. Discover alkaline water for the moments that make up your day.','water-terrace','Zubrex alkaline water on a sunlit terrace','alkaline-water.html','Discover alkaline water',True),('table','At the table','02 / The distinctive edit','Good company.<br>A little more <em>character.</em>','Clear glassware, a thoughtfully set table and a conversation worth staying for. Explore Black Drink for the occasions you make your own.','joyful-dining','Friends sharing Black Drink in a light-filled dining room','black-drink.html','Discover Black Drink',False),('home','At home','03 / The home edit','Your space.<br>Your <em>everyday ritual.</em>','Explore a water ionizer for your kitchen. Begin with your incoming water, your space and the questions that help you choose.','ionizer-kitchen','A Zubrex ionizer concept in an elegant light kitchen','ionizers.html','Explore home ionizers',True)]
    controls=''.join(f'<button type="button" id="moment-{key}" data-moment="{key}" aria-controls="moment-panel-{key}" aria-pressed="{str(i==0).lower()}"><span>0{i+1}</span>{label}<span aria-hidden="true">↗</span></button>' for i,(key,label,*_) in enumerate(options))
    panels=''.join(f'<div class="moment-panel" id="moment-panel-{key}" role="region" aria-labelledby="moment-{key}" {"hidden" if i else ""}><div class="moment-image">{image(img,alt,campaign=campaign)}</div><div class="moment-copy"><p class="eyebrow">{eyebrow}</p><h3>{title}</h3><p>{body}</p>{link(href,cta,True)}<a class="quiet-link" href="rituals.html">Explore everyday moments <span aria-hidden="true">→</span></a></div></div>' for i,(key,label,eyebrow,title,body,img,alt,href,cta,campaign) in enumerate(options))
    return f'<section class="section moment-section"><div class="wrap"><div class="section-head"><p class="eyebrow">A collection for your kind of day</p><h2>Find your <em>moment.</em></h2><p>Every setting has its own rhythm. Where will yours take you?</p></div><div class="moment-controls" hidden role="group" aria-label="Choose your moment">{controls}</div><div class="moment-panels">{panels}</div></div></section>'

