serving+=split('Begin with the basics','A clear glass.<br>A little intention.','<p>Clean, clear glassware lets the drink’s appearance take the lead. For a shared table, set out glasses before guests arrive and keep the product pack nearby so its label is easy to check.</p><p>Follow the pack’s directions for storage and serving temperature. Check the seal and date before opening, and use the opened product as directed on the label.</p>','black-pour','Black Drink and clear glassware on an elegant white studio table',campaign=False)
serving+=section('A hosting checklist','Four details worth considering.',content='<ol class="editorial-list"><li><h3>Give every guest a clear choice.</h3><p>Let guests know which product is being served. Keep ingredient and product information available rather than guessing when someone asks.</p></li><li><h3>Keep the setting simple.</h3><p>A light tablecloth, uncluttered glassware and a few natural details can create an inviting setting without competing with the drink.</p></li><li><h3>Serve with care.</h3><p>Use clean glasses and utensils. Follow the current pack’s storage and after-opening instructions, including any stated time limits.</p></li><li><h3>Plan the quantity.</h3><p>For a gathering or venue, share the guest count and date when enquiring. Confirm pack formats, availability and delivery arrangements in advance.</p></li></ol>')
serving+=related([('Meet Black Drink','Product details and the actual supplied pack.','black-drink.html','Discover the drink'),('For your next event','Talk through a hospitality or event enquiry.','hospitality.html','Explore hospitality'),('More everyday moments','Take inspiration from the everyday journal.','rituals.html','Keep exploring')])+cta()
add('serving-guide.html','The Serving Notes | Zubrex by Holy Elixir','Simple ideas for glassware, thoughtful hosting, product storage and serving the Zubrex collection.',serving,'Guides')

