science=intro('The product notes / pH & clarity','Understand<br><em>the essentials.</em>','A few useful terms, explained simply. Product measurements describe particular properties; they should be read in their proper context.')
science+=section('A starting point','What does pH describe?',content='''<div class="science-panel"><div class="ph-line" role="img" aria-label="Simplified pH scale: below 7 acidic, 7 neutral, above 7 alkaline"><span>0<br>Acidic</span><span>7<br>Neutral</span><span>14<br>Alkaline</span></div><div class="prose"><p>pH describes how acidic or basic an aqueous solution is. On the commonly used 0–14 scale, 7 is neutral, values below 7 are acidic and values above 7 are alkaline.</p><p>pH is logarithmic: a change of one unit represents a tenfold change in acidity. <a href="https://www.usgs.gov/water-science-school/science/ph-and-water" target="_blank" rel="noopener noreferrer">Read the USGS Water Science School explanation <span class="sr-only">(opens in a new tab)</span></a>.</p></div></div>''')
science+=section('Read measurements in context','A number is one part of the picture.',content=cards([('pH & product information','Read the declared pH alongside the product category, composition and storage directions. A pH value alone does not demonstrate a health outcome.','reading-labels.html','Read your label'),('Ingredients & appearance','Colour is an observable product feature. For the composition of a particular drink, use its current ingredient list rather than inferring from its appearance.','black-drink.html','Explore Black Drink'),('Ionization & installation','Ask for documentation for the exact ionizer model, including source-water suitability and any treatment requirements.','ionizers.html','Ask the right questions')]))
science+=section('When you want to know more','Ask for the specific detail.',content=faq([('Where can I find a current specification?','<p>Contact our team with the product name or appliance model. Ask for the current label, technical sheet or model documentation relevant to your question.</p>'),('Does this website make medical promises?','<p>Our collection is presented as drinks and home appliances. We do not describe the products as treatments or promise medical outcomes. For individual dietary or medical questions, seek advice from an appropriately qualified professional.</p>'),('Why might campaign artwork differ?','<p>Some visuals are creative concepts. They show a setting or presentation idea; current physical labels and confirmed product documentation provide the details for a purchase.</p>')]))
