def nav(file):
    groups=[('Collection',[('products.html','Explore the collection'),('alkaline-water.html','Alkaline Water'),('black-drink.html','Black Drink'),('ionizers.html','Water Ionizers')]),('Our world',[('about.html','Our perspective'),('rituals.html','Everyday journal'),('serving-guide.html','The serving notes')]),('Guides',[('benefits.html','Find your choice'),('reading-labels.html','Read your label'),('science.html','pH & product clarity'),('faq.html','Frequently asked')]),('For business',[('hospitality.html','Hospitality & events'),('partners.html','Trade & partnerships')])]
    features={
      'Collection':('products.html','collection','Zubrex collection campaign concept','Discover the collection','Three ways to make it yours.'),
      'Our world':('rituals.html','water-terrace','Zubrex alkaline water in a sunlit setting','The everyday journal','Make a moment of it.'),
      'Guides':('benefits.html','ionizer-kitchen','Zubrex ionizer concept in a light kitchen','A little product clarity','Find your everyday choice.'),
      'For business':('hospitality.html','black-occasion','Black Drink campaign concept in an evening setting','For hospitality & events','A place at your table.')}
    result='<ul id="site-menu">'
    for label,items in groups:
        href,img,alt,kicker,title=features[label]
        feature=f'<a class="nav-feature" href="{href}"><img src="assets/images/campaign/{img}-640.webp" alt="{alt}" width="640" height="{360 if img=="collection" else 427 if img=="ionizer-kitchen" else 640}" loading="lazy"><span><small>{kicker}</small><strong>{title}</strong><span aria-hidden="true">↗</span></span></a>'
        result+='<li><details class="nav-dropdown"><summary '+('class="nav-current"' if file in [f for f,t in items] else '')+'>'+label+'<span aria-hidden="true">⌄</span></summary><div class="nav-panel"><div class="nav-panel-links"><p class="eyebrow">'+label+'</p>'+''.join(f'<a href="{f}" {"aria-current=page" if file==f else ""}>{t}<span aria-hidden="true">↗</span></a>' for f,t in items)+'</div>'+feature+'</div></details></li>'
    return result+f'<li><a class="mobile-contact" href="contact.html" {"aria-current=page" if file=="contact.html" else ""}>Contact & enquiries</a></li></ul>'

